import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        start_pos = [int(next(iterator)) for _ in range(3)]
        matrix = []
        for _ in range(n):
            matrix.append(next(iterator))
    except StopIteration:
        return

    target_set = {1, 2, 3}

    def get_state_key(positions):
        return tuple(sorted(positions))

    start_key = get_state_key(start_pos)
    target_key = get_state_key(list(target_set))

    if start_key == target_key:
        print(0)
        return

    visited = {start_key: None}
    queue = deque([start_key])

    while queue:
        current = queue.popleft()
        if current == target_key:
            break

        u, v, w = current

        pairs = [(u, v), (u, w), (v, w)]

        for i in range(3):
            src = current[i]
            others = [current[j] for j in range(3) if j != i]
            color = matrix[others[0]-1][others[1]-1]

            for dest in range(1, n + 1):
                if dest in current:
                    continue
                if matrix[src-1][dest-1] == color:
                    new_positions = list(current)
                    new_positions[i] = dest
                    new_key = get_state_key(new_positions)

                    if new_key not in visited:
                        visited[new_key] = (current, src, dest)
                        queue.append(new_key)

    if target_key not in visited:
        print(-1)
        return

    path = []
    curr = target_key
    while visited[curr] is not None:
        prev, src, dest = visited[curr]
        path.append((src, dest))
        curr = prev

    path.reverse()
    print(len(path))
    for src, dest in path:
        print(f"{src} {dest}")

if __name__ == "__main__":
    solve()
